-- NI4E Events & Publications content seed
-- Run in the Supabase SQL editor after the base schema and event-registration migrations.
-- The events are authored programme concepts with proposed 2027 dates; confirm dates/venues internally before public launch.
on conflict (id) do update set title=excluded.title, summary=excluded.summary, body=excluded.body, metadata=excluded.metadata, published=excluded.published, event_start=excluded.event_start, event_end=excluded.event_end, updated_at=now();
