insert into public.site_content (id, content_type, title, slug, summary, body, metadata, published, event_start, event_end, updated_at)
values
('9c7b9f21-9b1f-4b17-8b24-0d4c72a10001','event','Engineering for a Sustainable Nigeria','engineering-for-a-sustainable-nigeria','A national technical conference on resilient infrastructure, energy access, engineering innovation and sustainable development. Explore practical case studies and cross-disciplinary solutions for Nigeria’s built and energy systems.','This two-day professional conference brings engineers, researchers, educators, public-sector stakeholders and industry partners together to discuss how engineering can advance resilient infrastructure and sustainable national development. Theme: Engineering for a Sustainable Nigeria — Energy, Infrastructure and Innovation. Key sessions cover reliable electricity delivery, renewable energy integration, infrastructure asset management, engineering ethics, local innovation and the role of young professionals. Participants can expect keynote talks, technical presentations, moderated panels and structured networking. Suitable for energy, electrical and electronics engineers; students and graduates; academics; project managers; technology providers; and public-sector professionals.',jsonb_build_object('event_type','Conference','venue','Abuja, Nigeria','time','9:00 AM – 4:30 PM daily','registration_open',true,'is_paid',false,'image_url','/images/ni4e-engineering-event-artwork.png','agenda',jsonb_build_array(jsonb_build_object('title','Opening & keynote','description','Engineering priorities for a resilient and sustainable Nigeria.'),jsonb_build_object('title','Energy transition','description','Renewables, storage, grid reliability and electricity access.'),jsonb_build_object('title','Infrastructure & innovation','description','Case studies on safe, durable and maintainable infrastructure.'),jsonb_build_object('title','Professional forum','description','Ethics, skills development, collaboration and closing discussion.'))),true,'2027-06-17T09:00:00+01:00','2027-06-18T16:30:00+01:00',now()),
('9c7b9f21-9b1f-4b17-8b24-0d4c72a10002','event','Powering Tomorrow: Smart Grids & Energy Access','powering-tomorrow-smart-grids-energy-access','A technical forum examining grid resilience, distributed renewables, storage, metering and practical routes to more reliable electricity services.','Theme: Powering Tomorrow — Renewables, Smart Grids and Energy Access. This focused technical forum explores the engineering and operational choices shaping electricity reliability in Nigeria. Sessions consider grid monitoring, distributed generation, battery storage, demand management, metering, safety and renewable-power integration. Case-study discussions connect design decisions with field implementation, maintenance and customer outcomes. Participants will leave with a clearer framework for evaluating grid-modernisation options and identifying opportunities for collaboration across utilities, developers, researchers and technology providers.',jsonb_build_object('event_type','Technical Forum','venue','Lagos, Nigeria','time','9:00 AM – 4:00 PM','registration_open',true,'is_paid',false,'image_url','/images/ni4e-engineering-event-artwork.png','agenda',jsonb_build_array(jsonb_build_object('title','Grid reliability briefing','description','Common causes of service interruptions and resilience measures.'),jsonb_build_object('title','Renewables & storage','description','Technical considerations for solar, storage and hybrid systems.'),jsonb_build_object('title','Smart systems panel','description','Metering, monitoring, automation and data-led operations.'),jsonb_build_object('title','Industry roundtable','description','Implementation barriers, partnerships and next steps.'))),true,'2027-03-12T09:00:00+01:00','2027-03-12T16:00:00+01:00',now()),
('9c7b9f21-9b1f-4b17-8b24-0d4c72a10003','event','Digital Engineering & Smart Systems Workshop','digital-engineering-smart-systems-workshop','A practical learning session on embedded systems, instrumentation, automation, electronics troubleshooting and digital tools for modern engineering practice.','Theme: Digital Engineering and Smart Systems — Automation, Electronics and Intelligent Infrastructure. The workshop connects engineering fundamentals with practical digital systems. Topics include sensors and instrumentation, embedded controllers, industrial automation, fault-finding methods, data acquisition and safe prototyping. Guided sessions and case-based discussion help participants connect technical concepts to real operational challenges. Suitable for early-career engineers, students, technicians, educators and professionals seeking a structured introduction to smart systems and applied electronics.',jsonb_build_object('event_type','Workshop','venue','Lagos, Nigeria','time','10:00 AM – 3:30 PM','registration_open',true,'is_paid',false,'image_url','/images/ni4e-engineering-event-artwork.png','agenda',jsonb_build_array(jsonb_build_object('title','Smart systems fundamentals','description','Sensors, signals, controllers and system architecture.'),jsonb_build_object('title','Instrumentation lab concepts','description','Measurement, data acquisition and troubleshooting workflows.'),jsonb_build_object('title','Automation case studies','description','Applying control and monitoring in engineering environments.'),jsonb_build_object('title','Career practice clinic','description','Technical portfolios, documentation and continuing learning.'))),true,'2027-02-20T10:00:00+01:00','2027-02-20T15:30:00+01:00',now())
